// Test block BarChart (Charts): A bar chart to compare amounts across categories or days, grouped side by side or stacked into a total.
//
// Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/charts/BarChart.md and its markup
// (kit/blocks/charts/BarChart.html, kit/blocks/charts/BarChart.2.html; source fff3d17e9264), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Then the chart {title} is described as {text}
//   When I show the chart {title} as a table
//   Then the chart {title} row {label} shows {value}
//   Then the chart {title} is in the {state} state
// States (from the card): Loaded, Loading, Empty, Error, Grouped or stacked, Horizontal, Many categories, Hover /
// touch on a point, Legend item, Theme change. Checked by the state step: Loaded, Loading, Empty, Error.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'BarChart';
export const ROUTE = '';
export const STATES = ["Loaded", "Loading", "Empty", "Error", "Grouped or stacked", "Horizontal", "Many categories", "Hover / touch on a point", "Legend item", "Theme change"];
export const DEFAULT_STATE = 'Loaded';
export const CHECKED_STATES = ["Loaded", "Loading", "Empty", "Error"];
export const DEMO = ["kit/blocks/charts/BarChart.html"];
export const SELF_TEST = [
  "Then the chart \"Orders per day\" is described as \"Saturday is busiest\"",
  "Then the chart \"Orders per day\" is in the \"Loaded\" state",
  "When I show the chart \"Orders per day\" as a table",
  "Then the chart \"Orders per day\" row Sat shows 83",
];

export const steps = new Registry({ block: BLOCK });

/** The BarChart block on a page: its controls, found as a person finds them (role and name, label, text). */
export class BarChart {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async card(title) {
    return p.control(this.page, { role: 'region', name: String(title), block: BLOCK });
  }

  async chart(title) {
    return p.control(await this.card(title), { role: 'img', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async chartAll(title) {
    return (await this.card(title)).getByRole('img');
  }

  async loading(title) {
    return p.control(await this.card(title), { css: '[aria-busy="true"]', block: BLOCK });
  }

  async alert(title) {
    return p.control(await this.card(title), { role: 'alert', block: BLOCK });
  }

  async tableToggle(title) {
    return p.control(await this.card(title), { text: 'Show as a table', block: BLOCK });
  }

  async tableRow(title, label) {
    return p.control(await this.card(title), { role: 'row', name: String(label), block: BLOCK });
  }

  /** Check one of the card's states: Loaded, Loading, Empty, Error. */
  async expectState(state, title) {
    const b = this;
    if (state === 'Loaded') {
      await p.expectVisible(await b.chart(title));
    } else if (state === 'Loading') {
      await p.expectVisible((await b.loading(title)).first());
    } else if (state === 'Empty') {
      await p.expectCount(await b.chartAll(title), 0);
    } else if (state === 'Error') {
      await p.expectVisible((await b.alert(title)).first());
    } else {
      throw new Error(`BarChart has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Then the chart {title} is described as {text}", async (world, { title, text }) => {
  const b = new BarChart(world.page, world.baseURL ?? '');
  await p.expectName(await b.chart(title), String(text));
}, { level: 'e2e' });

steps.step("When I show the chart {title} as a table", async (world, { title }) => {
  const b = new BarChart(world.page, world.baseURL ?? '');
  await p.click(await b.tableToggle(title));
}, { level: 'e2e' });

steps.step("Then the chart {title} row {label} shows {value}", async (world, { title, label, value }) => {
  const b = new BarChart(world.page, world.baseURL ?? '');
  await p.expectText(await b.tableRow(title, label), String(value));
}, { level: 'e2e' });

steps.step("Then the chart {title} is in the {state} state", async (world, { title, state }) => {
  const b = new BarChart(world.page, world.baseURL ?? '');
  await b.expectState(state, title);
}, { level: 'e2e' });
